import SwiftUI

/// Outlines of the clefs and the short rests, taken from the Noto Music font (Copyright 2022 The Noto Project Authors,
/// SIL Open Font License 1.1, see Resources/Fonts/OFL-NotoMusic.txt) and stored as path data, so the staff is drawn
/// the same on every device without a music font. The font's unit is 1/250 of the distance between two staff lines;
/// every outline's origin is on the staff's bottom line, y up.
enum MusicGlyph {
    case gClef, fClef, cClef, quarterRest, eighthRest, sixteenthRest

    /// Font units per staff space.
    static let unitsPerSpace: CGFloat = 250

    /// 0 x y: move, 1 x y: line, 2 cx cy x y: quadratic curve, 3: close.
    private var data: [Double] {
        switch self {
        case .gClef: return MusicGlyph.gClefData
        case .fClef: return MusicGlyph.fClefData
        case .cClef: return MusicGlyph.cClefData
        case .quarterRest: return MusicGlyph.quarterRestData
        case .eighthRest: return MusicGlyph.eighthRestData
        case .sixteenthRest: return MusicGlyph.sixteenthRestData
        }
    }

    /// The outline with its origin (the bottom staff line, at the glyph's left) at `origin`.
    func path(origin: CGPoint, space: CGFloat) -> Path {
        let scale = space / MusicGlyph.unitsPerSpace
        func point(_ x: Double, _ y: Double) -> CGPoint {
            CGPoint(x: origin.x + CGFloat(x) * scale, y: origin.y - CGFloat(y) * scale)
        }
        var path = Path()
        let values = data
        var index = 0
        while index < values.count {
            let code = Int(values[index])
            switch code {
            case 0:
                path.move(to: point(values[index + 1], values[index + 2]))
                index += 3
            case 1:
                path.addLine(to: point(values[index + 1], values[index + 2]))
                index += 3
            case 2:
                path.addQuadCurve(
                    to: point(values[index + 3], values[index + 4]),
                    control: point(values[index + 1], values[index + 2])
                )
                index += 5
            default:
                path.closeSubpath()
                index += 1
            }
        }
        return path
    }

    /// Width in staff spaces, for placing what follows.
    var width: CGFloat {
        switch self {
        case .gClef: return 2.6
        case .fClef: return 3.0
        case .cClef: return 2.8
        case .quarterRest: return 1.1
        case .eighthRest: return 1.2
        case .sixteenthRest: return 1.5
        }
    }

